// from bl_core.py line 25
inline qt::Mat nearest_psd(qt::Mat matrix, double eps) {
    matrix = (qt::broadcast(matrix, matrix.transpose(), qt::add_op{}) / 2.0).eval();
    auto [vals, vecs] = qt::eigh(matrix);
    vals = qt::maximum(vals, eps);
    return qt::matmul(qt::matmul(vecs, qt::diag(vals)), vecs.transpose());
}

// from bl_core.py line 32
/// Ledoit-Wolf (2004) shrinkage of the sample covariance toward a scaled
/// identity. X is a T x N matrix of (periodic) returns. Returns periodic cov.
inline qt::Mat ledoit_wolf_identity(const qt::Mat& X) {
    // X = np.asarray(X, dtype=float): already a float64 array, so NumPy returns it unchanged
    auto [t, n] = std::make_tuple(static_cast<long long>(X.rows()), static_cast<long long>(X.cols()));
    qt::Mat Xc = qt::broadcast(X, qt::as_row(qt::mean(X, 0)), qt::sub_op{});
    qt::Mat S = qt::matmul(Xc.transpose(), Xc) / static_cast<double>(t);
    double m = qt::trace(S) / static_cast<double>(n);
    double d2 = qt::sum((S - m * qt::eye(n)).square()) / static_cast<double>(n);
    // The textbook form of b_bar2 loops over every observation, building an
    // n x n outer product each time. With 15 years of daily data that is ~3,800
    // Python iterations per call, and a walk-forward backtest calls this once
    // per rebalance on an expanding window — twelve seconds of a fifteen-second
    // backtest went here. Expanding the Frobenius norm removes the loop:
    // 
    //   sum_i ||x_i x_i' - S||_F^2
    //     = sum_i (x_i'x_i)^2  -  2 sum_i x_i' S x_i  +  t ||S||_F^2
    // 
    // which is three vectorised reductions. Algebraically identical, no
    // approximation — verified against the loop to machine precision by a test.
    qt::Vec sq = qt::einsum1("ij,ij->i", {Xc, Xc}, {2, 2});  // ||x_i||^2 for each i
    double term1 = qt::dot(sq, sq);  // sum_i (x_i'x_i)^2
    double term2 = qt::sum(qt::matmul(Xc, S) * Xc);  // sum_i x_i' S x_i
    double term3 = static_cast<double>(t) * qt::sum(S * S);  // t ||S||_F^2
    double b_bar2 = (term1 - 2.0 * term2 + term3) / static_cast<double>(qt::ipow(t, 2)) / static_cast<double>(n);
    double b2 = std::min(b_bar2, d2);
    double a2 = d2 - b2;
    double shrink = d2 > 0 ? b2 / d2 : 1.0;
    qt::Mat sigma = shrink * m * qt::eye(n) + (d2 > 0 ? a2 / d2 : 0.0) * S;
    return sigma;
}

// from bl_core.py line 65
inline qt::Vec _ewma_weights(long long t, double halflife) {
    double lam = qt::pow(0.5, 1.0 / std::max(halflife, 1e-09));
    qt::Vec w = qt::pow(lam, qt::arange(static_cast<double>(qt::isub(t, 1LL)), -1.0, -1.0));
    return w / qt::sum(w);
}

// from bl_core.py line 71
/// Overlapping h-period compounded returns from a period-return panel.
///
/// Row k is the return between the price at k and the price at k + h, i.e. it
/// compounds periods k+1 through k+h. The output therefore has len(R) - h rows,
/// one per window that fully fits inside the sample.
inline qt::Mat horizon_returns(const qt::Mat& returns, long long h) {
    qt::Mat R = returns;
    h = std::max(1LL, h);
    if (h == 1 || R.rows() <= h) {
        return R;
    }
    qt::Mat g = qt::cumprod(1.0 + R, 0);
    return qt::broadcast(qt::block(g, h, qt::none, qt::none, qt::none), qt::block(g, qt::none, qt::ineg(h), qt::none, qt::none), qt::div_op{}) - 1.0;
}

// from bl_core.py line 86
/// Per-asset variance ratio VR(h) = Var(h-period) / (h x Var(1-period)).
///
/// The whole reason a holding period should change a portfolio. Scaling daily
/// variance by h assumes returns are independent from one day to the next. They
/// are not: an asset that mean-reverts is LESS risky over a year than its daily
/// volatility implies (VR < 1) and deserves more weight in a long hold, while a
/// trending one is MORE risky (VR > 1) and deserves less. Under strict i.i.d.
/// returns VR = 1 at every horizon and the holding period genuinely does not
/// matter -- which is why the app used to give the same answer for a week and a
/// year.
///
/// Overlapping windows mean the estimate is far noisier than the raw sample
/// size suggests: 3,780 daily observations contain only ~15 independent annual
/// ones. So VR is shrunk toward 1 by the effective sample count, which leaves a
/// weekly horizon essentially untouched and pulls a yearly one most of the way
/// back unless the evidence is strong. Clipped to [lo, hi] so a single freak
/// window cannot rescale a book.
inline qt::Vec variance_ratio(const qt::Mat& returns, long long h, double shrink_c, double lo, double hi) {
    qt::Mat R = returns;
    h = std::max(1LL, h);
    long long n = R.cols();
    if (h == 1 || R.rows() <= qt::imul(2LL, h)) {
        return qt::ones(n);
    }
    qt::Vec var1 = qt::var(R, 0, 1);
    qt::Mat Rh = horizon_returns(R, h);
    if (Rh.rows() < 3) {
        return qt::ones(n);
    }
    qt::Vec varh = qt::var(Rh, 0, 1);
    qt::Vec vr = qt::where(var1 > 1e-18, qt::broadcast(varh, static_cast<double>(h) * var1, qt::div_op{}), 1.0);
    vr = qt::where(vr.isFinite(), vr, 1.0);
    // Effective independent observations at this horizon, not the overlapping count.
    double n_eff = static_cast<double>(R.rows()) / static_cast<double>(h);
    double k = n_eff / (n_eff + shrink_c);
    vr = 1.0 + (vr - 1.0) * k;
    return qt::clip(vr, lo, hi);
}

// from bl_core.py line 127
/// Rescale each asset's variance by its variance ratio, keeping correlations.
///
/// Correlations are estimated well from daily data and badly from a handful of
/// overlapping annual windows, so only the volatilities are re-scaled here.
/// That is a deliberate compromise and the reason it is stated in the app.
inline qt::Mat apply_variance_ratio(const qt::Mat& cov_annual, const qt::Vec& vr) {
    qt::Mat S = cov_annual;
    qt::Vec d = qt::maximum(vr, 1e-12).sqrt();
    return nearest_psd(qt::broadcast(S, qt::outer(d, d), qt::mul_op{}));
}

// from bl_core.py line 298
/// Reverse optimisation: pi = delta * Sigma * w_mkt.
///
/// This is the whole trick of Black-Litterman. Instead of asking 'what returns
/// do I forecast?' (noisy, and the optimiser will amplify the noise), we ask
/// 'what returns would make today's market portfolio optimal?' and treat that
/// as the prior. Returned as EXCESS returns.
inline qt::Vec equilibrium_returns(double delta, const qt::Mat& Sigma, const qt::Vec& w_mkt) {
    return delta * qt::matvec(Sigma, w_mkt);
}

// from bl_core.py line 309
/// Unconstrained optimal weights for a given excess-return vector:
/// w = (delta * Sigma)^-1 * mu.  Note w = w_mkt exactly when mu = pi.
inline qt::Vec implied_confidence_weights(const qt::Vec& mu_excess, const qt::Mat& Sigma, double delta) {
    // Sigma = np.asarray(Sigma, dtype=float): already a float64 array, so NumPy returns it unchanged
    try {
        return qt::solve(delta * Sigma, mu_excess);
    } catch (const qt::LinAlgError&) {  // except LinAlgError
        return qt::matvec(qt::pinv(delta * Sigma), mu_excess);
    }
}

// from bl_core.py line 595
/// Omega = diag(P (tau Sigma) P').  The classic choice: a view is assumed to
/// be exactly as uncertain as the prior is about that same combination of
/// assets. Needs no user input at all.
inline qt::Mat omega_he_litterman(const qt::Mat& P, const qt::Mat& Sigma, double tau) {
    // P = np.asarray(P, dtype=float): already a float64 array, so NumPy returns it unchanged
    if (P.size() == 0) {
        return qt::zeros(0, 0);
    }
    qt::Mat M = qt::matmul(qt::matmul(P, tau * Sigma), P.transpose());
    qt::Vec d = qt::maximum(qt::diagonal(M), 1e-12);
    return qt::diag(d);
}

// from bl_core.py line 671
/// Black-Litterman posterior expected (excess) returns.
///
/// Uses the Sherman-Morrison-Woodbury form
///     mu = pi + tau*Sigma*P' (P tau*Sigma P' + Omega)^-1 (Q - P pi)
/// rather than the textbook
///     mu = [(tau Sigma)^-1 + P' Omega^-1 P]^-1 [(tau Sigma)^-1 pi + P' Omega^-1 Q]
/// They are algebraically identical, but the first inverts a k x k matrix
/// (k = number of views, usually 1-5) instead of an n x n one, and never
/// inverts Omega — which matters because a high-confidence view drives Omega
/// toward zero and makes Omega^-1 blow up.
inline qt::Vec posterior_mu(const qt::Vec& pi, const qt::Mat& Sigma, const std::optional<qt::Mat>& P, const qt::Vec& Q, const qt::Mat& Omega, double tau) {
    // pi = np.asarray(pi, dtype=float): already a float64 array, so NumPy returns it unchanged
    if (!P.has_value() || qt::value(P).size() == 0) {
        return pi;
    }
    // P = np.asarray(P, dtype=float): already a float64 array, so NumPy returns it unchanged
    // Q = np.asarray(Q, dtype=float): already a float64 array, so NumPy returns it unchanged
    // Omega = np.asarray(Omega, dtype=float): already a float64 array, so NumPy returns it unchanged
    qt::Mat tauS = tau * Sigma;
    qt::Mat A = qt::broadcast(qt::matmul(qt::matmul(qt::value(P), tauS), qt::value(P).transpose()), Omega, qt::add_op{});
    qt::Vec resid = qt::broadcast(Q, qt::matvec(qt::value(P), pi), qt::sub_op{});
    qt::Vec adj{};
    try {
        adj = qt::matvec(qt::matmul(tauS, qt::value(P).transpose()), qt::solve(A, resid));
    } catch (const qt::LinAlgError&) {  // except LinAlgError
        adj = qt::matvec(qt::matmul(tauS, qt::value(P).transpose()), qt::matvec(qt::pinv(A), resid));
    }
    return qt::broadcast(pi, adj, qt::add_op{});
}

// from bl_core.py line 700
/// Posterior covariance of returns: Sigma_p = Sigma + M, where M is the
/// posterior variance of the mean. Using this instead of Sigma is the
/// theoretically correct thing to do — it says 'I am not certain about the
/// expected returns either' — and it pushes the optimiser toward slightly more
/// diversified portfolios. Off by default because most practitioners, and most
/// textbook worked examples, just use Sigma.
inline qt::Mat posterior_sigma(const qt::Mat& Sigma, const std::optional<qt::Mat>& P, const qt::Mat& Omega, double tau) {
    // Sigma = np.asarray(Sigma, dtype=float): already a float64 array, so NumPy returns it unchanged
    qt::Mat tauS = tau * Sigma;
    if (!P.has_value() || qt::value(P).size() == 0) {
        return nearest_psd(Sigma + tauS);
    }
    // P = np.asarray(P, dtype=float): already a float64 array, so NumPy returns it unchanged
    qt::Mat A = qt::broadcast(qt::matmul(qt::matmul(qt::value(P), tauS), qt::value(P).transpose()), Omega, qt::add_op{});
    qt::Mat M{};
    try {
        M = tauS - qt::matmul(qt::matmul(tauS, qt::value(P).transpose()), qt::solve(A, qt::matmul(qt::value(P), tauS)));
    } catch (const qt::LinAlgError&) {  // except LinAlgError
        M = tauS - qt::matmul(qt::matmul(qt::matmul(qt::matmul(tauS, qt::value(P).transpose()), qt::pinv(A)), qt::value(P)), tauS);
    }
    return nearest_psd(Sigma + M);
}

// from bl_core.py line 764
inline std::tuple<double, double, double> portfolio_stats(const qt::Vec& w, const qt::Vec& mu, const qt::Mat& cov, double rf) {
    // w = np.asarray(w, dtype=float): already a float64 array, so NumPy returns it unchanged
    double ret = qt::dot(w, mu);
    double vol = std::sqrt(std::max(qt::dot(qt::vecmat(w, cov), w), 0.0));
    double sharpe = vol > 0 ? (ret - rf) / vol : qt::nan;
    return {ret, vol, sharpe};
}

// from bl_core.py line 772
inline double _downside_dev(const qt::Vec& w, const qt::Mat& R, double target_period, double freq_per_year) {
    qt::Vec p = qt::matvec(R, w);
    qt::Vec neg = qt::minimum(p - target_period, 0.0);
    double dd = std::sqrt(std::max(qt::mean(neg.square()), 1e-16));
    return dd * std::sqrt(freq_per_year);
}

// from bl_core.py line 779
inline double _cvar(const qt::Vec& w, const qt::Mat& R, double alpha) {
    qt::Vec p = qt::matvec(R, w);
    qt::Vec losses = -p;
    double var = qt::quantile(losses, alpha);
    qt::Vec tail = qt::select(losses, losses >= var);
    return tail.size() != 0 ? qt::mean(tail) : var;
}

// from bl_inference.py line 20
/// Mean block length ~ T^(1/3), the rate-optimal order for variance
/// estimation. About 13 for eight years of daily data.
inline long long default_block_length(long long T) {
    return std::max(2LL, qt::to_int(std::nearbyint(qt::pow(static_cast<double>(T), 1.0 / 3.0))));
}

// from bl_inference.py line 47
inline double _ann_mean(const qt::Vec& x, double fpy) {
    return qt::mean(x) * fpy;
}

// from bl_inference.py line 51
inline double _ann_sharpe(const qt::Vec& x, double fpy) {
    double sd = qt::std_(x, 1);
    return qt::where(sd > 0, qt::mean(x) / sd * std::sqrt(fpy), qt::nan);
}

