/// Newey-West (1994) plug-in bandwidth, floor(4 (T/100)^(2/9)).
inline long long newey_west_lag(long long T) {
    return qt::to_int(std::floor(4.0 * qt::pow(static_cast<double>(T) / 100.0, 2.0 / 9.0)));
}

// from bl_inference.py line 107
/// Newey-West long-run covariance of the columns of Y (already demeaned).
inline qt::Mat hac_cov(const qt::Mat& Y, std::optional<long long> lag) {
    // Y = np.asarray(Y, dtype=float): already a float64 array, so NumPy returns it unchanged
    long long T = Y.rows();
    long long L = !lag.has_value() ? newey_west_lag(T) : qt::value(lag);
    qt::Mat S = qt::matmul(Y.transpose(), Y) / static_cast<double>(T);
    for (long long j = 1; j < qt::iadd(L, 1LL); ++j) {
        double w = 1.0 - static_cast<double>(j) / (static_cast<double>(L) + 1.0);  // Bartlett kernel
        qt::Mat G = qt::matmul(qt::block(Y, j, qt::none, qt::none, qt::none).transpose(), qt::block(Y, qt::none, -j, qt::none, qt::none)) / static_cast<double>(T);
        qt::broadcast_into(S, w * qt::broadcast(G, G.transpose(), qt::add_op{}), qt::add_op{});
    }
    return S;
}

// from bl_inference.py line 185
/// One-sided p-value for hit rate > 50%, normal approximation to the
/// binomial on the number of independent checks.
inline std::optional<double> hit_rate_pvalue(std::optional<double> hit_rate, long long n_independent) {
    if (!hit_rate.has_value() || !(n_independent != 0)) {
        return std::nullopt;
    }
    double z = (qt::value(hit_rate) - 0.5) / std::sqrt(0.25 / static_cast<double>(n_independent));
    return 0.5 * std::erfc(z / std::sqrt(2));
}

// from bl_backtest.py line 82
/// Period returns of a basket bought at weights `w` and then LEFT ALONE.
///
/// The obvious-looking `R @ w` is not this. Applying a fixed weight vector to
/// every period silently rebalances the portfolio back to `w` every single
/// period — so a 'yearly rebalanced' strategy computed that way is really a
/// daily-rebalanced one that happens to re-optimise once a year, and every
/// rebalance frequency collapses to nearly the same result.
///
/// Here the holdings drift: each asset's value compounds at its own return, and
/// the portfolio return is the change in the total.
inline std::tuple<qt::Vec, qt::Vec> buy_and_hold_returns(const qt::Mat& R, const qt::Vec& w) {
    // R = np.asarray(R, dtype=float): already a float64 array, so NumPy returns it unchanged
    // w = np.asarray(w, dtype=float): already a float64 array, so NumPy returns it unchanged
    if (R.size() == 0) {
        return {qt::zeros(0), w};
    }
    qt::Mat growth = qt::cumprod(1.0 + R, 0);  // per-asset value path
    qt::Vec V = qt::matvec(growth, w);  // portfolio value path, V(0-)=1
    qt::Vec prev = qt::concat({qt::Vec(qt::vec({qt::sum(w)})), qt::Vec(qt::slice(V, qt::none, -1))});
    qt::Vec r = qt::where(prev.abs() > 1e-12, qt::broadcast(V, prev, qt::div_op{}) - 1.0, 0.0);
    // weights the portfolio has DRIFTED to by the end — what the next rebalance
    // actually trades away from, and therefore what turnover must be measured
    // against.
    qt::Vec end_val = qt::broadcast(w, qt::row(growth, -1).transpose(), qt::mul_op{});
    double tot = qt::sum(end_val);
    qt::Vec w_end = std::fabs(tot) > 1e-12 ? qt::Vec(end_val / tot) : qt::Vec(w);
    return {r, w_end};
}

